19	import java.time.LocalDate;
20	
21	/**
22	 * Thrown when a request to create an owner would exceed the daily registration limit, i.e. 100 or
23	 * more owners have already been created today (by {@code registrationDate}). The new owner is
24	 * rejected and the request is answered with 429 Too Many Requests.
25	 */
26	public class DailyRegistrationLimitException extends RuntimeException {
27	
28	    private final LocalDate date;
29	
30	    public DailyRegistrationLimitException(LocalDate date) {
31	        super("The maximum number of owners for today has already been reached");
32	        this.date = date;
33	    }
34	
35	    public LocalDate getDate() {
36	        return this.date;
37	    }
38	}
