62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        boolean bulkSignupWarning = isBulkSignupWarning();
100	        List<OwnerDto> ownerDtos = ownerMapper.toOwnerDtoCollection(owners);
101	        ownerDtos.forEach(ownerDto -> ownerDto.setBulkSignupWarning(bulkSignupWarning));
102	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
113	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
114	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        String address = normalizeAddress(ownerFieldsDto.getAddress());
121	        List<String> missingFields = new ArrayList<>();
122	        if (isBlank(ownerFieldsDto.getFirstName())) {
123	            missingFields.add("firstName");
124	        }
125	        if (isBlank(ownerFieldsDto.getLastName())) {
126	            missingFields.add("lastName");
127	        }
128	        if (isBlank(address)) {
129	            missingFields.add("address");
130	        }
131	        if (isBlank(ownerFieldsDto.getCity())) {
132	            missingFields.add("city");
133	        }
134	        if (isBlank(ownerFieldsDto.getTelephone())) {
135	            missingFields.add("telephone");
136	        }
137	        if (!missingFields.isEmpty()) {
138	            throw new MissingOwnerFieldsException(missingFields);
139	        }
140	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
141	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
142	        HttpHeaders headers = new HttpHeaders();
143	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
144	        owner.setAddress(address);
145	        owner.setTelephone(telephone);
146	        validatePostcode(owner.getPostcode(), owner.getRegion());
147	        if (sharesHousehold) {
148	            owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getAddress()));
149	        }
150	        // All duplicate detection is consolidated into the single derived identity key: a create is
151	        // rejected only when the new owner's whole identity key equals an existing owner's.
152	        if (isIdentityKeyInUse(owner.getIdentityKey())) {
153	            throw new DuplicateIdentityException(owner.getIdentityKey());
154	        }
155	        if (isCityAtCapacity(owner.getCity())) {
156	            throw new CityAtCapacityException(owner.getCity());
157	        }
158	        LocalDate effectiveDate = owner.getRegistrationDate() != null
159	            ? owner.getRegistrationDate() : LocalDate.now();
160	        LocalDate registrationDate = toBusinessDay(effectiveDate);
161	        if (isDailyRegistrationLimitReached(registrationDate)) {
162	            throw new DailyRegistrationLimitException(registrationDate);
163	        }
164	        owner.setRegistrationDate(registrationDate);
165	        owner.setCustomerCode(customerCodeFor(owner));
166	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
167	        if (sharesHousehold) {
168	            backfillHousehold(owner.getLastName(), owner.getAddress(), owner.getHouseholdId());
169	        }
170	        owner.setHouseholdSize(householdSizeAfterCreate(owner.getHouseholdId()));
171	        this.clinicService.saveOwner(owner);
172	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
173	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
174	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
175	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
176	        headers.setLocation(UriComponentsBuilder.newInstance()
177	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
178	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
179	    }
