package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when a request to create an owner supplies a {@code postcode} that is out of range for
 * the owner's city per the fixed region table (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
 * Carries the offending value so the exception handler can report it.
 */
public class InvalidPostcodeException extends RuntimeException {

    private final String rejectedValue;

    public InvalidPostcodeException(String rejectedValue) {
        super("Postcode is not valid for the owner's city region");
        this.rejectedValue = rejectedValue;
    }

    public String getRejectedValue() {
        return this.rejectedValue;
    }
}

/**
 * Handles {@link InvalidPostcodeException} raised when a request to create an owner supplies a
 * {@code postcode} that is out of range for the owner's city region.
 *
 * @param e The {@link InvalidPostcodeException} to be handled
 * @param request {@link HttpServletRequest} object referring to the current request.
 * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status,
 *         whose {@code errors} array names the {@code postcode} field.
 */
@ExceptionHandler(InvalidPostcodeException.class)
@ResponseBody
public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
    HttpStatus status = HttpStatus.BAD_REQUEST;
    logger.debug("Invalid postcode at {} {}: {}",
        request.getMethod(),
        request.getRequestURI(),
        e.getRejectedValue());
    ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
    detail.setProperty("errors", List.of("postcode"));
    return ResponseEntity.status(status).body(detail);
}

